def StrictConvexEdgeSupport (v : ZMod n → ℂ) : Prop :=
  ∀ i j : ZMod n, j ≠ i → j ≠ i + 1 →
    0 < crossR2 (v i) (v (i + 1)) (v j)

def ThreeLineCircle (P N : ZMod n → ℂ) (i : ZMod n) (C : ℂ) (r : ℝ) : Prop :=
  ⟪N (i - 1), P i - C⟫_ℝ = r ∧ ⟪N i, P i - C⟫_ℝ = r ∧
    ⟪N (i + 1), P (i + 1) - C⟫_ℝ = r
